for p in dom.descendants_and_self(root, Some(&W::p())) {
    let joined: String = dom
        .descendants(p, None)
        .into_iter()
        .filter(|&n| texts.iter().any(|t| dom.name_is(n, t)))
        .map(|n| dom.value(n))
        .collect();
    if joined.contains(needle) {
        return true;
    }
}

